package io.bmsride.monitor;
import android.bluetooth.*;import android.bluetooth.le.*;import android.content.*;import android.os.*;import java.util.*;
@SuppressWarnings("MissingPermission") final class Ble {
 interface Listener {void status(String s);void data(Protocol.Battery b);}
 final Context ctx;final Handler h=new Handler(Looper.getMainLooper());final BluetoothAdapter adapter;final Listener l;BluetoothGatt g;BluetoothGattCharacteristic tx;Protocol.Kind kind;Protocol.Decoder parser;boolean ready,busy,scanning;int reg=3,lkPoll=0;long lastWrite;final Map<String,BluetoothDevice> devices=new LinkedHashMap<>();final Map<String,Integer> rssi=new HashMap<>();final Map<String,String> names=new HashMap<>();
 String name(BluetoothDevice d){String n=names.get(d.getAddress());if(n==null||n.trim().isEmpty())n=d.getName();return n==null||n.trim().isEmpty()?"未知设备":n;}
 boolean supports(BluetoothDevice d){return name(d).startsWith("LK8625-");}
 static UUID id(int v){return UUID.fromString(String.format(Locale.US,"0000%04x-0000-1000-8000-00805f9b34fb",v));}
 Ble(Context c,Listener l){ctx=c;this.l=l;adapter=c.getSystemService(BluetoothManager.class).getAdapter();}
 final ScanCallback scan=new ScanCallback(){public void onScanResult(int type,ScanResult r){h.post(()->{if(!scanning)return;String a=r.getDevice().getAddress();devices.put(a,r.getDevice());rssi.put(a,r.getRssi());String n=r.getScanRecord()==null?null:r.getScanRecord().getDeviceName();if(n!=null&&!n.trim().isEmpty())names.put(a,n);});} public void onScanFailed(int e){h.post(()->{stopScan();l.status("扫描失败 "+e);});}};
 void scan(){stopScan();devices.clear();rssi.clear();names.clear();if(adapter==null||!adapter.isEnabled()||adapter.getBluetoothLeScanner()==null){l.status("请打开蓝牙");return;}adapter.getBluetoothLeScanner().startScan(scan);scanning=true;l.status("扫描中");h.removeCallbacks(scanTimeout);h.postDelayed(scanTimeout,8000);}
 final Runnable scanTimeout=()->stopScan();
 void stopScan(){h.removeCallbacks(scanTimeout);if(scanning&&adapter!=null&&adapter.getBluetoothLeScanner()!=null)adapter.getBluetoothLeScanner().stopScan(scan);scanning=false;}
 void connect(BluetoothDevice d,Protocol.Kind k){close();kind=k;if(k==Protocol.Kind.BAOLIAN&&!supports(d)){l.status("只允许手动选择 LK8625 设备");return;}parser=new Protocol.Decoder(k);l.status("连接中");g=d.connectGatt(ctx,false,cb,BluetoothDevice.TRANSPORT_LE);}
 void close(){stopScan();ready=false;busy=false;tx=null;reg=3;lkPoll=0;if(g!=null){BluetoothGatt old=g;g=null;old.disconnect();old.close();}l.data(null);}
 void fail(String msg){close();l.status(msg);}
 void tick(){if(!ready||g==null||tx==null)return;if(busy){if(SystemClock.elapsedRealtime()-lastWrite>3000)fail("BLE 写入超时");return;}if(kind==Protocol.Kind.BAOLIAN){if(!parser.lk.confirmed){if(!parser.lk.model.isEmpty()){fail("保锂安型号不匹配");return;}reg=2;}else{int[] cycle={0x1e,0x20,0x09,0x1e,0x20,0x1f,0x1e,0x20,0x1e,0x20};reg=cycle[lkPoll++%cycle.length];}}byte[] b=Protocol.request(kind,reg);if(kind==Protocol.Kind.JBD)reg=reg==3?4:3;int props=tx.getProperties();int mode=kind==Protocol.Kind.BAOLIAN?BluetoothGattCharacteristic.WRITE_TYPE_NO_RESPONSE:(props&BluetoothGattCharacteristic.PROPERTY_WRITE)!=0?BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT:BluetoothGattCharacteristic.WRITE_TYPE_NO_RESPONSE;tx.setWriteType(mode);tx.setValue(b);busy=g.writeCharacteristic(tx);lastWrite=SystemClock.elapsedRealtime();if(!busy)l.status("读取请求失败");}
 final BluetoothGattCallback cb=new BluetoothGattCallback(){
  public void onConnectionStateChange(BluetoothGatt x,int status,int state){h.post(()->{if(x!=g)return;if(status!=0||state==BluetoothProfile.STATE_DISCONNECTED){fail("蓝牙已断开 "+status);return;}if(state==BluetoothProfile.STATE_CONNECTED&&!x.discoverServices())fail("服务发现失败");});}
  public void onServicesDiscovered(BluetoothGatt x,int status){h.post(()->{if(x!=g)return;if(status!=0){fail("服务发现失败");return;}boolean j=kind==Protocol.Kind.JBD;boolean lk=kind==Protocol.Kind.BAOLIAN;BluetoothGattService s=x.getService(id(j?0xff00:0xffe0));if(!lk&&s==null){fail("协议服务不匹配");return;}UUID rxid=lk?UUID.fromString("00010203-0405-0607-0809-0a0b0c0dffe1"):id(j?0xff01:0xffe1),txid=lk?UUID.fromString("00010203-0405-0607-0809-0a0b0c0dffe2"):id(j?0xff02:0xffe1);BluetoothGattCharacteristic rx=null;for(BluetoothGattService svc:lk?x.getServices():Collections.singletonList(s)){for(BluetoothGattCharacteristic c:svc.getCharacteristics()){int p=c.getProperties();if(c.getUuid().equals(rxid)&&(p&BluetoothGattCharacteristic.PROPERTY_NOTIFY)!=0)rx=c;if(c.getUuid().equals(txid)&&(p&(lk?BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE:(BluetoothGattCharacteristic.PROPERTY_WRITE|BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE)))!=0)tx=c;}}if(rx==null||tx==null||!x.setCharacteristicNotification(rx,true)){fail("找不到读写特征");return;}BluetoothGattDescriptor d=rx.getDescriptor(id(0x2902));if(d==null){fail("缺少通知描述符");return;}d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);if(!x.writeDescriptor(d))fail("订阅失败");});}
  public void onDescriptorWrite(BluetoothGatt x,BluetoothGattDescriptor d,int status){h.post(()->{if(x!=g)return;if(status!=0){fail("订阅失败");return;}ready=true;l.status("已订阅，等待有效20串数据");});}
  public void onCharacteristicWrite(BluetoothGatt x,BluetoothGattCharacteristic c,int s){h.post(()->{if(x!=g)return;busy=false;if(s!=0)l.status("读取请求失败 "+s);});}
  public void onCharacteristicChanged(BluetoothGatt x,BluetoothGattCharacteristic c){byte[] b=c.getValue().clone();h.post(()->{if(x!=g)return;Protocol.Battery d=parser.feed(b,System.currentTimeMillis());if(d!=null){l.data(d);l.status(kind==Protocol.Kind.BAOLIAN?"保锂安 LK8625 · 实时数据":"BMS 实时数据");}});}
 };
}
